// samples = latences en ms (non triées). Renvoie { p50, p95, p99 }.
// Méthode du rang le plus proche : sur la COPIE triée croissante de n valeurs,
// le p-ième percentile est l'élément d'index ceil(p/100 * n) - 1 (borné à n-1).
// Piège classique : renvoyer la MOYENNE — elle cache les pics de la queue.
export function percentiles(samples) {
  // TODO : trie une copie, puis lis p50/p95/p99 par rang le plus proche.
  const mean = samples.reduce((s, x) => s + x, 0) / samples.length;
  return { p50: mean, p95: mean, p99: mean };
}

